	sourceScript := tengo.NewScript([]byte(`
		g := 10
		make := func(start) {
			x := start
			return func(v) { x += v; return x + 5 + g }
		}
		fn := make(1)
		holder := {"nested": [{"fn": fn}]}
	`))
	source, err := sourceScript.Run()
	require.NoError(t, err)
	sourceFn := source.Get("fn").Object()
	require.Equal(t, int64(17), callInt(t, sourceFn, callableIntObject(1))) // capture is 2

	clone := source.Clone()
	cloneFn := clone.Get("fn").Object()
	require.Equal(t, int64(18), callInt(t, cloneFn, callableIntObject(1)))
